window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[205]={"id":"205","numero":205,"titre":"Hémoptysie","objectifs":[{"id":"205-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une hémoptysie","contenu":"<p><span class=\"kw-def\">Hémoptysie</span> = saignement issu des <span class=\"kw-def\">voies respiratoires sous-glottiques</span>, extériorisé ou non, traduisant une anomalie pouvant siéger à <strong>tous <span class=\"kw-clinique\">les</span> étages</strong> de l'appareil respiratoire.</p>\n\n      <h4>Origine vasculaire — deux circulations</h4>\n      <p>Il existe des <em>shunts physiologiques</em> entre <span class=\"kw-clinique\">les</span> deux circulations pour prévenir la <span class=\"kw-clinique\">nécrose</span> en cas d'ischémie. L'<span class=\"kw-clinique\">hémoptysie</span> est en règle alimentée par la circulation bronchique (haute pression) — la circulation pulmonaire ne contribue qu'à<span class=\"kw-chiffre\"> 5 %</span> des cas mais avec une gravité accrue.</p>\n\n      <div class=\"table-wrap\">\n        <table class=\"matrix\">\n          <thead>\n            <tr><th>Compartiment</th><th>Fréquence</th><th>Caractéristiques</th></tr>\n          </thead>\n          <tbody>\n            <tr>\n              <th><span class=\"kw-def\">Circulation bronchique systémique</span></th>\n              <td><span class=\"kw-chiffre\">95 %</span> des cas</td>\n              <td><strong>Régime :</strong> grande circulation, <span class=\"kw-chiffre\">haute pression</span><br><strong>Débit :</strong> bas (<span class=\"kw-chiffre\">2 %</span> du DC)<br><strong>Artères :</strong> bronchiques (← aorte thoracique descendante)<br><strong>Veines :</strong> bronchiques (→ azygos, VCS)</td>\n            </tr>\n            <tr>\n              <th><span class=\"kw-def\">Circulation pulmonaire</span></th>\n              <td><span class=\"kw-chiffre\">5 %</span> des cas</td>\n              <td><strong>Régime :</strong> petite circulation, <span class=\"kw-chiffre\">basse pression</span><br><strong>Débit :</strong> haut (<span class=\"kw-chiffre\">100 %</span> du DC)<br><strong>Artères :</strong> pulmonaires (← VD)<br><strong>Veines :</strong> pulmonaires (→ OG)</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n\n      <h4>Mécanisme principal — Hypervascularisation systémique (HVS)</h4>\n      <p>L'<span class=\"kw-clinique\">hémoptysie</span> d'origine bronchique systémique relève d'une <span class=\"kw-def\">HVS</span> par ouverture des <em>anastomoses</em> entre <span class=\"kw-clinique\">les</span> deux circulations. Deux mécanismes coexistent :</p>\n      <ul>\n        <li><strong>Destruction du lit capillaire</strong> = <span class=\"kw-clinique\">mécanisme principal de l'HVS</span>. Toutes étiologies confondues : <span class=\"kw-clinique\">granulome</span>, <span class=\"kw-clinique\">fibrose</span>, <span class=\"kw-clinique\">cancer</span>, cicatrice d'une <span class=\"kw-clinique\">lésion</span> pulmonaire. L'<em>hyperhémie infectieuse</em> (bronchectasies, <span class=\"kw-clinique\">abcès</span>) y participe.</li>\n        <li><strong>Défaut d'apport de la circulation pulmonaire</strong> (entraîne une <em>néoangiogénèse</em>) : <span class=\"kw-clinique\">artérite de Takayasu</span>, <span class=\"kw-clinique\">HTAP post-embolique</span>, <span class=\"kw-clinique\">cardiopathies congénitales</span>.</li>\n      </ul>\n\n      <h4>Mécanisme accessoire — Origine pulmonaire (<span class=\"kw-chiffre\">5 %</span>)</h4>\n      <ul>\n        <li><strong>Saignement artériel pulmonaire</strong> (plus grave car reçoit <span class=\"kw-chiffre\">100 %</span> du DC) : <span class=\"kw-clinique\">érosion</span> par <span class=\"kw-clinique\">tumeur</span>, <span class=\"kw-clinique\">nécrose</span> infectieuse (<span class=\"kw-clinique\">tuberculose</span>), anévrysme mycotique (<span class=\"kw-clinique\">aspergillose</span>).</li>\n        <li><strong>Saignement de la membrane alvéolo-capillaire</strong> par augmentation de perméabilité → <span class=\"kw-def\">hémorragie intra-alvéolaire</span>. Deux mécanismes :\n          <ul>\n            <li><em>Mécanique</em> : augmentation de la pression veineuse capillaire (<span class=\"kw-clinique\">rétrécissement mitral</span>).</li>\n            <li><em>Immunologique</em> : dépôts de complexes immuns (<span class=\"kw-clinique\">Lupus érythémateux disséminé</span>), lésions capillaires (<span class=\"kw-clinique\">GPA</span>, <span class=\"kw-clinique\">MPA</span>, <span class=\"kw-clinique\">Goodpasture</span>).</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>Confirmation diagnostique du saignement alvéolaire</h4>\n      <p>Hémorragie intra-alvéolaire confirmée par <span class=\"kw-bio\">fibroscopie + LBA</span> avec <span class=\"kw-bio\">score de Golde &gt; 100</span> — ou présence de <span class=\"kw-chiffre\">≥ 20-30 %</span> de sidérophages. Tableau d'<span class=\"kw-clinique\">anémie</span> associé.</p>\n      <p><em>Méthode du <span class=\"kw-def\">score</span> de Golde :</em> décompte de <span class=\"kw-chiffre\">100 macrophages alvéolaires</span> colorés au <span class=\"kw-bio\">Perls</span>, chaque macrophage coté de <span class=\"kw-chiffre\">0 à 4</span> selon sa teneur en hémosidérine → échelle <span class=\"kw-chiffre\">0-400</span>. Le seuil pathologique retenu est <span class=\"kw-alerte\">&gt; 100</span> (équivalent à une charge intracellulaire modérée à massive sur la majorité des macrophages).</p>","frequence":0},{"id":"205-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’hémoptysie et argumenter le diagnostic différentiel","contenu":"<h4>Aspects cliniques caractéristiques</h4>\n      <ul>\n        <li>Sang <span class=\"kw-clinique\">rouge vif</span>, <span class=\"kw-clinique\">spumeux</span>, <span class=\"kw-clinique\">aéré</span>, extériorisé par la bouche au cours d'<span class=\"kw-clinique\">efforts de toux</span> ✅</li>\n        <li><strong>Prodromes / signes d'accompagnement évocateurs :</strong>\n          <ul>\n            <li><span class=\"kw-clinique\">Chaleur rétrosternale</span></li>\n            <li><span class=\"kw-clinique\">Grésillement laryngé</span></li>\n            <li><span class=\"kw-clinique\">Goût métallique</span> dans la bouche</li>\n            <li><span class=\"kw-clinique\">Angoisse</span></li>\n          </ul>\n        </li>\n        <li>Auscultation : <span class=\"kw-clinique\">crépitants</span> possibles.</li>\n      </ul>\n\n      <h4>Diagnostics différentiels — tableau de discrimination</h4>\n      <div class=\"table-wrap\">\n        <table class=\"matrix\">\n          <thead>\n            <tr><th>Entité</th><th>Origine</th><th>Caractéristiques discriminantes</th></tr>\n          </thead>\n          <tbody>\n            <tr>\n              <th><span class=\"kw-def\">Hémoptysie</span></th>\n              <td>Sous-glottique (pulmonaire)</td>\n              <td><strong>Sang :</strong> rouge vif, spumeux, aéré<br><strong>Geste :</strong> effort de <span class=\"kw-clinique\">toux</span><br><strong>Prodromes :</strong> chaleur rétrosternale, grésillement, goût métallique</td>\n            </tr>\n            <tr>\n              <th><span class=\"kw-def\">Hématémèse</span></th>\n              <td>Digestif haut</td>\n              <td><strong>Sang :</strong> rouge foncé, non aéré, débris alimentaires<br><strong>Geste :</strong> <span class=\"kw-clinique\">vomissement</span><br><strong>Piège :</strong> sang dans l'estomac peut être une <span class=\"kw-clinique\">hémoptysie</span> déglutie ⚠️</td>\n            </tr>\n            <tr>\n              <th><span class=\"kw-def\">Saignement ORL</span></th>\n              <td>Sus-glottique (VAS)</td>\n              <td><strong>Topographie :</strong> épistaxis postérieure, saignement pharyngo-laryngé<br><strong>Geste :</strong> déglutition, mouchage<br><strong>Repère :</strong> sang sans <span class=\"kw-clinique\">bulle</span>, sans <span class=\"kw-clinique\">toux</span> préalable</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n\n      <h4>Stratégie pour écarter <span class=\"kw-clinique\">les</span> différentiels</h4>\n      <ul>\n        <li><strong>Rechercher un effort de <span class=\"kw-clinique\">toux</span></strong> contemporain du saignement (interrogatoire dirigé).</li>\n        <li><strong><span class=\"kw-imagerie\">Endoscopie</span></strong> selon orientation : œso-gastrique (<span class=\"kw-clinique\">hématémèse</span>), bronchique (<span class=\"kw-clinique\">hémoptysie</span> confirmée), ORL (épistaxis postérieure). La <span class=\"kw-clinique\">fibroscopie ORL</span> peut être réalisée en chambre rapidement.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Piège classique</strong> ⚠️ — le sang retrouvé dans l'estomac peut correspondre à une <span class=\"kw-clinique\">hémoptysie déglutie</span>. Ne pas conclure trop vite à une <span class=\"kw-clinique\">hématémèse</span> sans rechercher activement la <span class=\"kw-clinique\">toux</span> et <span class=\"kw-clinique\">les</span> prodromes respiratoires.</div>\n\n      <h4>Paraclinique de confirmation</h4>\n      <ul>\n        <li><span class=\"kw-radio\">RXT</span> : infiltrats ou opacités liés au <span class=\"kw-radio\">comblement alvéolaire</span>.</li>\n        <li><span class=\"kw-radio\">TDM</span> : plage en <span class=\"kw-radio\">verre dépoli</span> ou <span class=\"kw-radio\">condensation alvéolaire</span>, éventuellement <span class=\"kw-radio\">atélectasie</span>.</li>\n        <li><span class=\"kw-clinique\">Troubles ventilatoires</span> possibles (<em>shunt vrai fonctionnel</em> par comblement des alvéoles par du sang).</li>\n        <li><span class=\"kw-bio\">LBA</span> : hémorragie intra-alvéolaire diagnostiquée pour un <span class=\"kw-bio\">score de Golde &gt; 100</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 203 — <span class=\"kw-clinique\">Dyspnée</span> · 204 — <span class=\"kw-clinique\">Toux</span> · 207 — Opacité intra-thoracique Adulte/Enfant</em></p>","frequence":3},{"id":"205-3","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir rechercher des signes de gravité","contenu":"<div class=\"callout callout-danger\"><strong>Le risque c'est l'<span class=\"kw-alerte\">asphyxie</span>, PAS la spoliation sanguine.</strong> Volume des voies de conduction = <span class=\"kw-chiffre\">150-200 mL</span>. Le retentissement hémodynamique est exceptionnel et tardif : l'absence de <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span> ou d'anémie est <strong>faussement rassurante</strong>.</div>\n\n      <h4>Dogme — toute <span class=\"kw-clinique\">hémoptysie</span> est une <span class=\"kw-alerte\">urgence</span></h4>\n      <p>Même en cas de <em>faible abondance</em>, l'<span class=\"kw-clinique\">hémoptysie</span> doit toujours être considérée comme une <span class=\"kw-alerte\">urgence</span> 🔥 :</p>\n      <ul>\n        <li>Une <span class=\"kw-clinique\">hémoptysie</span> <span class=\"kw-alerte\">minime</span> peut récidiver sous forme massive.</li>\n        <li>Une <span class=\"kw-clinique\">hémoptysie</span> de <span class=\"kw-alerte\">faible abondance</span> peut révéler une pathologie pulmonaire grave sous-jacente.</li>\n      </ul>\n\n      <h4>Évaluation clinique — abondance du saignement</h4>\n      <div class=\"table-wrap\">\n        <table class=\"matrix\">\n          <thead>\n            <tr><th>Seuil de gravité</th><th><span class=\"kw-def\">Terrain</span></th><th>Référence</th></tr>\n          </thead>\n          <tbody>\n            <tr>\n              <th><span class=\"kw-alerte\">≥ 200 mL / 24 h</span></th>\n              <td>Sujet sain</td>\n              <td>Définition usuelle (CEP)</td>\n            </tr>\n            <tr>\n              <th><span class=\"kw-alerte\">&gt; 100 mL en 1 fois</span></th>\n              <td>Tout <span class=\"kw-def\">terrain</span></td>\n              <td>MIR — abondance grave d'emblée</td>\n            </tr>\n            <tr>\n              <th><span class=\"kw-alerte\">&gt; 50 mL / 24 h</span></th>\n              <td><span class=\"kw-clinique\">Insuffisant respiratoire chronique</span></td>\n              <td>Seuil abaissé sur <span class=\"kw-def\">terrain</span> fragile</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n\n      <h4>Repères pratiques de quantification</h4>\n      <p>À l'hôpital : <span class=\"kw-clinique\">récipients gradués</span>. Hors hôpital, ordres de grandeur :</p>\n      <div class=\"table-wrap\">\n        <table class=\"matrix\">\n          <thead>\n            <tr><th>Contenant</th><th>Volume estimé</th></tr>\n          </thead>\n          <tbody>\n            <tr><th><span class=\"kw-chiffre\">Cuillère à café</span></th><td>≈<span class=\"kw-chiffre\"> 5 mL</span></td></tr>\n            <tr><th><span class=\"kw-chiffre\">Cuillère à soupe</span></th><td>≈<span class=\"kw-chiffre\"> 10 mL</span></td></tr>\n            <tr><th><span class=\"kw-chiffre\">Crachoir / verre</span></th><td>≈<span class=\"kw-chiffre\"> 100-150 mL</span></td></tr>\n            <tr><th><span class=\"kw-chiffre\">Haricot / bol</span></th><td>≈<span class=\"kw-chiffre\"> 300-500 mL</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n\n      <h4><span class=\"kw-def\">Critères de</span> <span class=\"kw-def\">terrain</span> (gravité indirecte)</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Insuffisance respiratoire chronique</span> sous-jacente — <span class=\"kw-alerte\"><span class=\"kw-def\">critère de</span> gravité</span> par lui-même.</li>\n        <li><span class=\"kw-clinique\">Comorbidités respiratoires</span> (<span class=\"kw-def\">BPCO</span>, fibrose, <span class=\"kw-def\">IRC</span>…).</li>\n        <li><span class=\"kw-clinique\">Cardiopathie ischémique</span> pouvant justifier le maintien d'antithrombotiques.</li>\n        <li><strong>Persistance</strong> du saignement, particulièrement <span class=\"kw-alerte\">sous vasoconstricteurs</span> (justifie une <span class=\"kw-def\">surveillance</span> rapprochée).</li>\n      </ul>\n\n      <h4>Retentissement clinique</h4>\n      <ul>\n        <li>Présence de signes de <span class=\"kw-clinique\">détresse respiratoire</span>.</li>\n        <li><span class=\"kw-alerte\">FR &gt; 30 / min</span>.</li>\n        <li><span class=\"kw-alerte\">SpO₂ &lt; 85 %</span> en <span class=\"kw-def\">air</span> ambiant.</li>\n        <li>Recours à <span class=\"kw-alerte\">oxygénothérapie à haut débit</span> ou <span class=\"kw-alerte\">ventilation mécanique</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 208 — <span class=\"kw-ci\">Insuffisance respiratoire</span> chronique</em></p>","frequence":3},{"id":"205-4","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités d’initiation du traitement symptomatique en urgence","contenu":"<h4>Orientation immédiate</h4>\n      <p><strong><span class=\"kw-alerte\">Hospitalisation</span> en milieu spécialisé</strong> 🔥 : <span class=\"kw-alerte\">soins intensifs</span> respiratoires, unité de <span class=\"kw-def\">surveillance</span> continue ou réanimation. L'<span class=\"kw-clinique\">hémoptysie</span> grave relève d'une prise en charge multidisciplinaire (pneumologue, réanimateur, radiologue interventionnel, parfois chirurgien thoracique).</p>\n\n      <h4>Mesures symptomatiques immédiates</h4>\n      <ul>\n        <li><strong>Vérifier l'absence d'obstruction des VAS</strong> (caillots de sang obstruant <span class=\"kw-clinique\">les</span> voies pharyngolaryngées).</li>\n        <li><strong>Arrêt systématique des antithrombotiques</strong> (<span class=\"kw-ttt\">antiagrégants</span>, <span class=\"kw-ttt\">anticoagulants</span>) en cas d'<span class=\"kw-clinique\">hémoptysie</span> sévère.</li>\n        <li><strong><span class=\"kw-ttt\">Oxygénothérapie</span></strong> avec interface adaptée : objectif <span class=\"kw-chiffre\">SpO₂ ≥ 90-92 %</span> ⭐⭐⭐, avec monitoring continu.</li>\n        <li><strong>Décubitus latéral du côté qui saigne</strong> ⭐⭐⭐ (si le côté est connu) — protection du <em>poumon sain</em> contre l'inondation alvéolaire controlatérale.</li>\n        <li><strong><span class=\"kw-imagerie\">Endoscopie</span> d'hémostase locale</strong> ⭐⭐ — discutée si <span class=\"kw-clinique\">angioTDM non disponible immédiatement</span>, ou pour temporiser dans l'attente de l'<span class=\"kw-ttt\">artério-embolisation</span> (cf. obj-7).</li>\n      </ul>\n\n      <h4>Vasoconstricteurs — <span class=\"kw-ttt\">terlipressine</span> IV</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Terlipressine</span> par voie <span class=\"kw-ttt\">IV</span> en <span class=\"kw-chiffre\">première intention</span> pendant la phase d'invest<span class=\"kw-chiffre\">iga</span>tion.</li>\n        <li>Indication à <em>mesurer</em> : peut rendre <span class=\"kw-clinique\">l'artériographie bronchique ultérieure plus difficile</span> (spasme artériel).</li>\n        <li><strong>Inefficace</strong> si saignement d'origine <span class=\"kw-clinique\">artérielle pulmonaire</span> — artère pulmonaire dépourvue de cellules musculaires lisses.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-ttt\">Terlipressine</span> — <span class=\"kw-ci\">contre-indication</span> formelle si <span class=\"kw-etio\">athérosclérose</span></strong> ⚠️ : risque d'<span class=\"kw-alerte\">IDM</span>, d'<span class=\"kw-alerte\">AVC</span> et d'<span class=\"kw-alerte\">ischémie aiguë de membre inférieur</span>. Toujours interroger sur <span class=\"kw-clinique\">les</span> antécédents vasculaires avant la prescription.</div>\n\n      <h4>Protection des voies aériennes (<span class=\"kw-clinique\">hémoptysie</span> sévère)</h4>\n\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ttt\">VNI</span> formellement <span class=\"kw-ci\">contre-indiquée</span></strong> ❌❌❌ en cas d'<span class=\"kw-clinique\">hémoptysie</span>. Recourir à l'<span class=\"kw-ttt\">intubation</span> et à la ventilation mécanique invasive si la protection des VAS est nécessaire.</div>\n\n      <ul>\n        <li><strong>1ʳᵉ intention :</strong> <span class=\"kw-ttt\">sonde d'intubation à double lumière</span>, idéale pour protéger le poumon non saignant (usage techniquement difficile, expertise requise).</li>\n        <li><strong>2ⁿᵈᵉ intention</strong>, à défaut :\n          <ul>\n            <li><span class=\"kw-ttt\">Intubation sélective</span> du côté qui ne saigne pas.</li>\n            <li>Ou mise en place d'une <span class=\"kw-ttt\">sonde à ballonnet</span> dans la bronche souche du poumon qui saigne.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":1},{"id":"205-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription d’un bilan initial","contenu":"<h4>Bilan <span class=\"kw-ttt\">biologique</span> systématique</h4>\n      <div class=\"table-wrap\">\n        <table class=\"matrix\">\n          <thead>\n            <tr><th>Examen</th><th>Objectif</th><th>Particularités</th></tr>\n          </thead>\n          <tbody>\n            <tr>\n              <th><span class=\"kw-bio\">Gaz du sang artériel</span></th>\n              <td>Évaluer l'hématose en <span class=\"kw-alerte\">urgence</span> si <span class=\"kw-clinique\">hémoptysie</span> grave</td>\n              <td><strong>MIR :</strong> effet shunt classique (<span class=\"kw-clinique\">hypoxémie + hypocapnie + alcalose respiratoire</span> par hyperventilation compensatrice)<br><strong>CEP :</strong> recherche signes de sévérité (<span class=\"kw-clinique\">hypoxémie + hypercapnie</span>)</td>\n            </tr>\n            <tr>\n              <th><span class=\"kw-bio\">NFS - plaquettes</span></th>\n              <td>Anémie (rare et tardive), thrombopénie</td>\n              <td>Souvent peu spoliante au début</td>\n            </tr>\n            <tr>\n              <th><span class=\"kw-bio\">Bilan d'hémostase</span></th>\n              <td>Éliminer un trouble coagulation</td>\n              <td><span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">INR</span>, <span class=\"kw-bio\">TCK</span>, <span class=\"kw-bio\">activité anti-Xa</span>, dosage spécifique d'<span class=\"kw-ttt\">AOD</span> selon molécule</td>\n            </tr>\n            <tr>\n              <th><span class=\"kw-bio\">Groupe sanguin / RAI</span></th>\n              <td>Anticipation transfusionnelle</td>\n              <td>Systématique même si la transfusion est exceptionnelle</td>\n            </tr>\n            <tr>\n              <th><span class=\"kw-bio\">Créatininémie + ionogramme</span></th>\n              <td>Évaluation systémique</td>\n              <td>Ajout MIR — utile avant injection iodée et <span class=\"kw-ttt\">terlipressine</span></td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n\n      <h4>Interrogatoire ciblé orientant la cause</h4>\n      <ul>\n        <li><strong>Antécédents respiratoires :</strong> <span class=\"kw-clinique\">bronchectasies</span>, <span class=\"kw-clinique\">tuberculose</span> (active ou séquellaire), <span class=\"kw-clinique\">cancer broncho-pulmonaire</span>.</li>\n        <li><strong>Antécédents cardiaques :</strong> <span class=\"kw-clinique\">cardiopathie</span>, <span class=\"kw-clinique\">rétrécissement mitral</span>, <span class=\"kw-clinique\">insuffisance cardiaque gauche</span>.</li>\n        <li><strong>Histoire récente :</strong> alitement, <span class=\"kw-ttt\">chirurgie</span> (orientent vers <span class=\"kw-clinique\">EP</span>).</li>\n        <li><strong>Prises médicamenteuses :</strong> <span class=\"kw-ttt\">anticoagulants</span>, <span class=\"kw-ttt\">pénicillamine</span> ; <strong>expositions toxiques :</strong> <span class=\"kw-ttt\">isocyanates</span>, <span class=\"kw-ttt\">crack</span>.</li>\n        <li><strong>Aspect du sang :</strong> rouge foncé (saignement plus ancien) ou rouge vif (saignement actif).</li>\n      </ul>\n\n      <h4>Examen physique structuré</h4>\n      <ul>\n        <li><strong>Constantes vitales :</strong> <span class=\"kw-clinique\">SpO₂</span>, <span class=\"kw-clinique\">tension artérielle</span>, <span class=\"kw-clinique\">pouls</span>, <span class=\"kw-clinique\">FR</span>.</li>\n        <li><strong>Recherche de signes de mauvaise tolérance respiratoire</strong> (et plus rarement hémodynamique).</li>\n        <li><strong>Gêne latéralisée</strong> à l'auscultation ou à la palpation, pouvant orienter le côté qui saigne.</li>\n      </ul>\n\n      <h4>Signes physiques orientant l'étiologie</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Hippocratisme digital</span> → bronchectasies, cancer, cardiopathie <span class=\"kw-etio\">congénitale</span>.</li>\n        <li><span class=\"kw-clinique\">Signes cliniques de cancer</span> (altération état général, <span class=\"kw-clinique\">adénopathies</span>, Pancoast-Tobias).</li>\n        <li><span class=\"kw-clinique\">Souffle valvulaire</span> (rétrécissement mitral, <span class=\"kw-def\">OAP</span> <span class=\"kw-etio\">hémorragique</span>).</li>\n        <li><span class=\"kw-clinique\">Signes de vascularite systémique</span> (<span class=\"kw-def\">purpura</span>, atteinte ORL, glomérulonéphrite — <span class=\"kw-clinique\">GPA</span> / MPA / Goodpasture).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":4},{"id":"205-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la sémiologie en imagerie d’une hémoptysie","contenu":"<h4><span class=\"kw-imagerie\">RXT</span> — réalisable en attente de l'<span class=\"kw-imagerie\">angioTDM</span></h4>\n      <p>La <span class=\"kw-imagerie\"><span class=\"kw-imagerie\">radiographie</span> thoracique</span> peut être réalisée dans l'attente de l'<span class=\"kw-imagerie\">angioTDM</span> (MIR) pour localiser le siège du saignement :</p>\n      <ul>\n        <li><strong>Signes directs :</strong> <span class=\"kw-radio\">syndrome alvéolaire localisé</span>.</li>\n        <li><strong>Signes indirects :</strong>\n          <ul>\n            <li><span class=\"kw-radio\">Syndrome bronchique</span> avec d'éventuels <span class=\"kw-radio\">troubles de la ventilation</span> (atélectasie).</li>\n            <li>Présence de la <span class=\"kw-imagerie\">lésion source</span> du saignement : cavité, tumeur, <span class=\"kw-clinique\">nodule</span>, masse.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <figure>\n        <img src=\"../assets/images/205/rp-hemoptysie-tuberculose.png\" alt=\"Radiographie de thorax de face montrant des opacités alvéolaires du lobe supérieur droit en rapport avec le comblement hémorragique sur une tuberculose pulmonaire\">\n        <figcaption><strong><span class=\"kw-imagerie\">Radiographie</span> de thorax de face</strong> : <span class=\"kw-radio\">opacités alvéolaires du lobe supérieur droit</span> en rapport avec le comblement <span class=\"kw-etio\">hémorragique</span> et la cause de l'<span class=\"kw-clinique\">hémoptysie</span> (ici, une <span class=\"kw-clinique\">tuberculose</span>). La <span class=\"kw-imagerie\">RXT</span> <strong>peut être normale</strong>. <em>Source : banque imagerie « Imagerie à connaître » (item 205).</em></figcaption>\n      </figure>\n\n      <h4><span class=\"kw-imagerie\">AngioTDM</span> thoracique — examen de 1ʳᵉ intention ✅</h4>\n      <p><span class=\"kw-imagerie\">TDM</span> thoracique <em>injecté</em>, avec <span class=\"kw-imagerie\">temps aortique</span> ET <span class=\"kw-imagerie\">temps artériel pulmonaire</span>. Quatre apports indissociables :</p>\n      <div class=\"table-wrap\">\n        <table class=\"matrix\">\n          <thead>\n            <tr><th>Apport</th><th>Sémiologie</th></tr>\n          </thead>\n          <tbody>\n            <tr>\n              <th><span class=\"kw-def\">Diagnostic positif</span></th>\n              <td><span class=\"kw-radio\">Syndrome alvéolaire</span>, <span class=\"kw-radio\">verre dépoli</span>, <span class=\"kw-radio\">condensation alvéolaire</span>, atélectasies éventuelles</td>\n            </tr>\n            <tr>\n              <th>Nature de la <span class=\"kw-clinique\">lésion</span></th>\n              <td><strong>Type :</strong> tumeur, caverne, bronchectasies, MAV<br><strong>Caractérisation :</strong> taille, contours, hypervascularisation</td>\n            </tr>\n            <tr>\n              <th>Localisation du saignement</th>\n              <td><span class=\"kw-radio\">Verre dépoli localisé</span> = topographie probable de l'hémorragie alvéolaire active</td>\n            </tr>\n            <tr>\n              <th>Cartographie vasculaire</th>\n              <td>Repère précisément la <span class=\"kw-imagerie\">vascularisation artérielle bronchique</span> — oriente l'<span class=\"kw-ttt\">embolisation</span></td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n\n      <figure>\n        <img src=\"../assets/images/205/scanner-verre-depoli.jpg\" alt=\"TDM thoracique en fenêtre parenchymateuse — plage en verre dépoli avec alvéoles partiellement remplies de sang\">\n        <figcaption><strong>Fig. 1 — <span class=\"kw-imagerie\">TDM</span> (fenêtre parenchymateuse)</strong> : plage en <span class=\"kw-radio\">verre dépoli</span> témoignant d'alvéoles partiellement remplies de sang.</figcaption>\n      </figure>\n\n      <figure>\n        <img src=\"../assets/images/205/scanner-condensation-alveolaire.jpg\" alt=\"TDM thoracique coupe axiale/sagittale — condensation alvéolaire par inondation alvéolaire\">\n        <figcaption><strong>Fig. 2 — <span class=\"kw-imagerie\">TDM</span> (coupes axiale / sagittale)</strong> : <span class=\"kw-radio\">condensation alvéolaire</span> suite à l'inondation des alvéoles par du sang.</figcaption>\n      </figure>\n\n      <figure>\n        <img src=\"../assets/images/205/scanner-mixte-mediastin.jpg\" alt=\"TDM thoracique — verre dépoli + condensation alvéolaire, coupe médiastinale\">\n        <figcaption><strong>Fig. 3 — <span class=\"kw-imagerie\">TDM</span> (coupe médiastinale)</strong> : association <span class=\"kw-radio\">verre dépoli + condensation alvéolaire</span>.</figcaption>\n      </figure>\n\n      <figure>\n        <img src=\"../assets/images/205/tdm-hemoptysie-cancer.png\" alt=\"TDM thoracique en coupe axiale, fenêtre parenchymateuse, montrant une masse de contours irréguliers du lobe supérieur droit en rapport avec une tumeur pulmonaire et du verre dépoli périphérique en rapport avec l'hémorragie intra-alvéolaire\">\n        <figcaption><strong>Fig. 4 — <span class=\"kw-imagerie\">TDM</span> thoracique (coupe axiale, fenêtre parenchymateuse)</strong> : <span class=\"kw-radio\">masse de contours irréguliers du lobe supérieur droit</span> (tumeur pulmonaire = cause) + <span class=\"kw-radio\">verre dépoli périphérique</span> (hémorragie intra-alvéolaire). <span class=\"kw-clinique\">Hémoptysie</span> sur <span class=\"kw-clinique\">cancer pulmonaire</span>. <em>Source : banque imagerie « Imagerie à connaître » (item 205).</em></figcaption>\n      </figure>\n\n      <h4><span class=\"kw-imagerie\">Endoscopie</span> bronchique — 2ⁿᵈᵉ intention</h4>\n      <p>Intérêt limité en <span class=\"kw-alerte\">urgence</span>, non systématique, pas toujours utilisable. Quatre indications principales :</p>\n      <ul>\n        <li><strong>Confirmer le diagnostic</strong> d'<span class=\"kw-clinique\">hémoptysie</span> en cas de doute avec un différentiel.</li>\n        <li><strong>Localiser la topographie</strong> du saignement si le <span class=\"kw-imagerie\">scanner</span> trouve des lésions <em>multiples</em> ou en cas d'incertitude.</li>\n        <li><strong>Identifier la cause</strong> en cas de <span class=\"kw-clinique\">tumeur bronchique proximale</span> accessible.</li>\n        <li><strong>Réaliser une hémostase locale en <span class=\"kw-alerte\">urgence</span></strong> (<span class=\"kw-clinique\">hémoptysie</span> persistante, dans l'attente de l'<span class=\"kw-ttt\">artério-embolisation</span>).</li>\n      </ul>\n\n      <h4>Autres examens selon le contexte</h4>\n      <ul>\n        <li><span class=\"kw-bio\">Recherche de BK</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">expectorations</span> si suspicion de <span class=\"kw-def\">tuberculose</span>.</li>\n        <li><span class=\"kw-bio\">Sérologie ± antigénémie aspergillaire</span>.</li>\n        <li><span class=\"kw-clinique\">ECG</span> et <span class=\"kw-clinique\">ETT</span> si suspicion d'<span class=\"kw-def\">OAP</span> à forme <span class=\"kw-etio\">hémorragique</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-danger\"><strong>Artériographie bronchique = traitement, PAS diagnostic</strong> ❌. Elle n'a aucune place dans la démarche purement diagnostique. Ne se conçoit que dans la perspective d'une <span class=\"kw-ttt\">embolisation</span> (cf. obj-7).</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant</em></p>","frequence":3},{"id":"205-7","rang":"B","rubrique":"Étiologies","titre":"Connaître les éléments du diagnostic étiologique d’une hémoptysie","contenu":"<div class=\"callout callout-info\"><strong>Mnémo <span class=\"kw-clinique\">ABCDE</span></strong> — <span class=\"kw-clinique\">les</span> 5 étiologies principales d'<span class=\"kw-clinique\">hémoptysie</span> :<br><strong>A</strong>spergillome (prolifération mycélienne sur cavité séquellaire)<br><strong>B</strong>K — <span class=\"kw-def\">tuberculose</span> active ou séquellaire<br><strong>C</strong>ancer broncho-pulmonaire<br><strong>D</strong>ilatations bronchiques (bronchectasies)<br><strong>E</strong>mbolie pulmonaire</div>\n\n      <h4>Tableau exhaustif par catégorie</h4>\n      <div class=\"table-wrap\">\n        <table class=\"matrix\">\n          <thead>\n            <tr><th>Catégorie</th><th>Étiologies</th></tr>\n          </thead>\n          <tbody>\n            <tr>\n              <th>Bronchique</th>\n              <td><strong>Bronchectasies :</strong> <span class=\"kw-clinique\">dilatations des bronches</span> localisées ou diffuses<br><strong><span class=\"kw-etio\">Génétique</span> :</strong> <span class=\"kw-clinique\">mucoviscidose</span></td>\n            </tr>\n            <tr>\n              <th>Infectieuse</th>\n              <td><strong><span class=\"kw-def\">Tuberculose</span> :</strong> <span class=\"kw-clinique\">BK actif</span> (<span class=\"kw-clinique\">érosion</span> vasculaire par caverne) ou <span class=\"kw-clinique\">séquellaire</span> (DDB secondaires, aspergillome sur caverne détergée)<br><strong>Fungique :</strong> <span class=\"kw-clinique\">aspergillome</span>, <span class=\"kw-clinique\">aspergillose invasive ou semi-invasive</span><br><strong><span class=\"kw-etio\">Bactérienne</span> :</strong> <span class=\"kw-clinique\">pneumopathies nécrosantes</span>, <span class=\"kw-clinique\">abcès pulmonaire</span></td>\n            </tr>\n            <tr>\n              <th><span class=\"kw-etio\">Tumorale</span></th>\n              <td><strong>Malignes :</strong> <span class=\"kw-clinique\">cancers broncho-pulmonaires primitifs</span>, <span class=\"kw-clinique\">métastases pulmonaires</span><br><strong>Bénignes :</strong> <span class=\"kw-clinique\">tumeur carcinoïde</span></td>\n            </tr>\n            <tr>\n              <th>Vasculaire</th>\n              <td><strong>Thrombo-<span class=\"kw-etio\">embolique</span> :</strong> <span class=\"kw-clinique\">embolie pulmonaire</span><br><strong>Malformations :</strong> <span class=\"kw-clinique\">MAV pulmonaires</span> isolées ou dans le cadre d'une <span class=\"kw-clinique\">maladie de Rendu-Osler</span><br><strong>Pariétal :</strong> <span class=\"kw-clinique\">anévrysme de l'artère pulmonaire</span>, anévrysme <span class=\"kw-etio\">iatrogène</span></td>\n            </tr>\n            <tr>\n              <th>Hémorragies alvéolaires</th>\n              <td><strong>Mécaniques :</strong> <span class=\"kw-clinique\">insuffisance cardiaque gauche</span>, <span class=\"kw-clinique\">HTAP</span>, <span class=\"kw-clinique\">rétrécissement mitral</span> ⭐<br><strong>Médicamenteuses :</strong> <span class=\"kw-ttt\">pénicillamine</span>, <span class=\"kw-ttt\">anticoagulants</span> ; <strong>toxiques :</strong> <span class=\"kw-ttt\">isocyanates</span>, <span class=\"kw-ttt\">crack</span><br><strong>Immunologiques :</strong> vascularites (<span class=\"kw-clinique\">GPA</span>, <span class=\"kw-clinique\">MPA</span>, <span class=\"kw-clinique\">Goodpasture</span>), collagénoses (<span class=\"kw-clinique\">Lupus</span>)</td>\n            </tr>\n            <tr>\n              <th>Traumatique</th>\n              <td><strong>Externe :</strong> <span class=\"kw-clinique\">érosion</span> par <span class=\"kw-clinique\">fragment costal</span>, <span class=\"kw-clinique\">contusion pulmonaire</span><br><strong>Interne :</strong> <span class=\"kw-clinique\">rupture trachéo-bronchique</span>, <span class=\"kw-clinique\">corps étranger</span></td>\n            </tr>\n            <tr>\n              <th>Idiopathique</th>\n              <td><strong><span class=\"kw-clinique\">Hémoptysie</span> cryptogénique :</strong> diagnostic d'élimination après <span class=\"kw-radio\">TDM thoracique</span> + <span class=\"kw-clinique\">endoscopie bronchique</span> négatives. Représente <span class=\"kw-chiffre\">10-25 %</span> des cas selon <span class=\"kw-clinique\">les</span> séries.</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n\n      <div class=\"callout callout-warn\"><strong>La <span class=\"kw-def\">BPCO</span> seule n'est PAS une cause d'<span class=\"kw-clinique\">hémoptysie</span></strong> ❌. Toute <span class=\"kw-clinique\">hémoptysie</span> chez un patient <span class=\"kw-def\">BPCO</span> impose la recherche d'une maladie sous-jacente — en particulier un <span class=\"kw-clinique\">cancer broncho-pulmonaire</span>. Conduite obl<span class=\"kw-chiffre\">iga</span>toire : <span class=\"kw-radio\">endoscopie bronchique</span> + <span class=\"kw-radio\">TDM thoracique</span> systématiques + <strong><span class=\"kw-def\">surveillance</span> prolongée</strong>.</div>\n\n      <h4>Éléments d'orientation à l'interrogatoire</h4>\n      <ul>\n        <li><strong>Antécédents respiratoires</strong> : <span class=\"kw-def\">tuberculose</span> connue, DDB, cancer broncho-pulmonaire en cours de <span class=\"kw-def\">suivi</span>.</li>\n        <li><strong>Antécédents cardiaques</strong> : valvulopathie mitrale, IC gauche, cardiopathie <span class=\"kw-etio\">congénitale</span>.</li>\n        <li><strong>Contexte récent</strong> : alitement, <span class=\"kw-ttt\">chirurgie</span>, immobilisation prolongée (orientent <span class=\"kw-clinique\">EP</span>).</li>\n        <li><strong>Prises médicamenteuses</strong> : <span class=\"kw-ttt\">anticoagulants</span> (<span class=\"kw-ttt\">AVK</span>, <span class=\"kw-ttt\">AOD</span>), <span class=\"kw-ttt\">pénicillamine</span>.</li>\n        <li><strong>Expositions</strong> : <span class=\"kw-ttt\">isocyanates</span> (peinture polyuréthane), <span class=\"kw-ttt\">crack</span> (toxicomanie inhalée).</li>\n      </ul>\n\n      <h4>Signes physiques orientant la cause</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Hippocratisme digital</span> : DDB, cancer, cardiopathie <span class=\"kw-etio\">congénitale</span>.</li>\n        <li><span class=\"kw-clinique\">Signes cliniques de cancer</span> (<span class=\"kw-clinique\">AEG</span>, syndrome <span class=\"kw-etio\">paranéoplasique</span>, Pancoast-Tobias).</li>\n        <li><span class=\"kw-clinique\">Souffle de rétrécissement mitral</span>.</li>\n        <li><span class=\"kw-clinique\">Signes de vascularite systémique</span> (<span class=\"kw-def\">purpura</span>, sinusite chronique, atteinte rénale).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 154 — Infection bronchopulmonaire communautaire · 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte · 192 — Pathologie <span class=\"kw-etio\">auto-immune</span> · 193 — <span class=\"kw-def\">Vascularite</span> systémique · 209 — <span class=\"kw-def\">BPCO</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 233 — Valvulopathie · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 309 — Tumeurs du poumon</em></p>","frequence":4},{"id":"205-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux de prise en charge d’une hémoptysie et leur hiérarchisation en fonction de sa gravité","contenu":"<h4>Principe général — prise en charge multidisciplinaire</h4>\n      <p>La prise en charge des hémoptysies graves est <strong>multidisciplinaire</strong> : pneumologues, réanimateurs, radiologues interventionnels et parfois chirurgiens thoraciques. Quatre axes hiérarchisés :</p>\n      <ol>\n        <li><strong><span class=\"kw-alerte\">Hospitalisation</span></strong> en <span class=\"kw-alerte\">soins intensifs</span> respiratoires, <span class=\"kw-def\">surveillance</span> continue ou réanimation — indispensable.</li>\n        <li><strong>Vasoconstricteurs + O₂</strong> en 1ʳᵉ intention, pendant <span class=\"kw-clinique\">les</span> invest<span class=\"kw-chiffre\">iga</span>tions diagnostiques.</li>\n        <li><strong>Embolisation artérielle bronchique</strong> d'emblée ou en cas d'échec des vasoconstricteurs.</li>\n        <li><strong><span class=\"kw-ttt\">Chirurgie</span></strong> si la <span class=\"kw-clinique\">lésion</span> est accessible à une résection limitée, à distance ou en aigu en cas d'échec d'embolisation.</li>\n      </ol>\n\n      <h4>Algorithme de hiérarchisation (MIR)</h4>\n      <div class=\"table-wrap\">\n        <table class=\"matrix\">\n          <thead>\n            <tr><th>Étape</th><th>Décision</th><th>Conduite</th></tr>\n          </thead>\n          <tbody>\n            <tr>\n              <th>1 — Triage</th>\n              <td><span class=\"kw-imagerie\">AngioTDM</span> disponible <em>immédiatement</em> et patient stable ?</td>\n              <td><strong>Oui</strong> → <span class=\"kw-imagerie\">AngioTDM</span><br><strong>Non</strong> → <span class=\"kw-ttt\">terlipressine IV</span> + <span class=\"kw-ttt\">endoscopie d'hémostase</span></td>\n            </tr>\n            <tr>\n              <th>2 — AngioTDM</th>\n              <td>Rechercher <span class=\"kw-clinique\">les</span> 4 <span class=\"kw-alerte\">signes de gravité</span></td>\n              <td><span class=\"kw-alerte\">IRA</span><br><span class=\"kw-alerte\">grande abondance</span><br><span class=\"kw-alerte\">comorbidité respi / CV</span><br><span class=\"kw-alerte\">anticoagulant en cours</span></td>\n            </tr>\n            <tr>\n              <th>3 — Orientation</th>\n              <td>Selon présence de <span class=\"kw-alerte\">signes de gravité</span></td>\n              <td><strong>Absence :</strong> <span class=\"kw-def\">surveillance</span> milieu adapté<br><strong>Présence :</strong> <span class=\"kw-ttt\">radiologie vasculaire interventionnelle</span> → si échec : <span class=\"kw-ttt\">chirurgie thoracique</span></td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n\n      <h4>Quatre moyens thérapeutiques</h4>\n      <div class=\"table-wrap\">\n        <table class=\"matrix\">\n          <thead>\n            <tr><th>Moyen</th><th>Modalités</th></tr>\n          </thead>\n          <tbody>\n            <tr>\n              <th>Traitement médical</th>\n              <td><strong>VAS :</strong> vérifier l'absence d'obstruction par caillots<br><strong>Antithrombotiques :</strong> <span class=\"kw-ci\">arrêt systématique</span> si <span class=\"kw-clinique\">hémoptysie</span> sévère<br><strong>O₂ :</strong> objectif <span class=\"kw-chiffre\">SpO₂ ≥ 90-92 %</span> ⭐⭐⭐ + monitoring<br><strong>Position :</strong> <span class=\"kw-ttt\">décubitus latéral du côté qui saigne</span> ⭐⭐⭐<br><strong>Vasoconstricteurs :</strong> <span class=\"kw-ttt\">terlipressine IV</span> (rappel <span class=\"kw-ci\">CI si athérosclérose</span> ⚠️)<br><strong>Protection VAS :</strong> <span class=\"kw-ttt\">intubation</span> par <span class=\"kw-ttt\">sonde double lumière</span> &gt; intubation sélective &gt; sonde à ballonnet<br><strong><span class=\"kw-ttt\">VNI</span> :</strong> <span class=\"kw-ci\">contre-indiquée</span> ❌</td>\n            </tr>\n            <tr>\n              <th>Radiologie interventionnelle</th>\n              <td><strong>Méthode :</strong> <span class=\"kw-ttt\">embolisation artérielle bronchique</span> par <span class=\"kw-imagerie\">artériographie</span> — méthode de choix pour <span class=\"kw-clinique\">hémoptysie</span> grave ✅<br><strong>Étape 1 :</strong> repérage des artères en cause<br><strong>Étape 2 :</strong> identification de l'anomalie (élargissement, hypervascularisation, shunt systémo-pulmonaire, flaque de PDC)<br><strong>Étape 3 :</strong> injection de <span class=\"kw-ttt\">particules</span> ou <span class=\"kw-ttt\">spirales</span><br><strong>Voie d'abord (origine artérielle pulmonaire) :</strong> veine fémorale<br><strong>Voie d'abord (origine artérielle bronchique) :</strong> artère fémorale<br><strong>Limites :</strong> requiert une expertise non disponible dans tous <span class=\"kw-clinique\">les</span> centres ; <span class=\"kw-ttt\">terlipressine</span> préalable complique l'examen (spasme)<br><strong>Complications rares mais graves :</strong> <span class=\"kw-alerte\">paraplégie</span> (embolisation d'un rameau médullaire), <span class=\"kw-alerte\">nécrose œsophagienne</span> (embolisation d'un rameau œsophagien)</td>\n            </tr>\n            <tr>\n              <th>Traitement topique</th>\n              <td><strong>Instillation locale :</strong> <span class=\"kw-ttt\">sérum physiologique à 4 °C</span> ou <span class=\"kw-ttt\">solution adrénalinée</span> — indication anecdotique, <span class=\"kw-clinique\">hémoptysie</span> non grave<br><strong>Toilette bronchique :</strong> possible, mais <span class=\"kw-ci\">mobilisation du caillot à proscrire</span></td>\n            </tr>\n            <tr>\n              <th>Traitement chirurgical</th>\n              <td><strong>Nature :</strong> traitement <em>radical</em> — arrête le saignement et prévient la récidive<br><strong>Conditions :</strong> zone limitée, unilatérale, autorisant une <span class=\"kw-ttt\">lobectomie</span> (plus rarement <span class=\"kw-ttt\">pneumonectomie</span>) ; fonction respiratoire compatible<br><strong>Timing à froid :</strong> à distance de l'<span class=\"kw-clinique\">hémoptysie</span>, <span class=\"kw-clinique\">lésion</span> accessible à une résection limitée<br><strong>Timing à chaud :</strong> uniquement en cas d'<span class=\"kw-clinique\">échec de l'embolisation</span> — <span class=\"kw-alerte\">mortalité ≈ 40 %</span></td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n\n      <div class=\"callout callout-danger\"><strong>Artériographie bronchique = traitement, PAS diagnostic</strong> ❌. Elle n'a aucune place dans la démarche purement diagnostique : ne se conçoit que dans la perspective d'une <span class=\"kw-ttt\">embolisation</span>.</div>\n\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-ttt\">Terlipressine</span> — CI si <span class=\"kw-etio\">athérosclérose</span></strong> ⚠️ (risque <span class=\"kw-alerte\">IDM</span>, <span class=\"kw-alerte\">AVC</span>, <span class=\"kw-alerte\">ischémie aiguë MI</span>). Inefficace si saignement d'origine artérielle pulmonaire (artère pulmonaire dépourvue de cellules musculaires lisses).</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 209 — <span class=\"kw-def\">BPCO</span> · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 309 — Tumeurs du poumon</em></p>","frequence":5}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> toute <span class=\"kw-clinique\">hémoptysie</span> est une <span class=\"kw-alerte\">urgence</span> (dogme), même minime — elle peut récidiver sous forme massive ou révéler une pathologie pulmonaire ; forme massive = <span class=\"kw-alerte\">urgence vitale</span> par <span class=\"kw-alerte\">risque d'asphyxie</span><br><strong>Fenêtre :</strong> prise en charge immédiate ; le danger vient de l'<span class=\"kw-alerte\">asphyxie</span> (volume des voies de conduction <span class=\"kw-chiffre\">150-200 mL</span>), pas de la spoliation sanguine (<span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span> exceptionnel et tardif, absence d'anémie faussement rassurante)<br><strong>1er geste :</strong> <span class=\"kw-ttt\">oxygénothérapie</span> (objectif <span class=\"kw-chiffre\">SpO2 ≥ 90-92%</span>), libérer <span class=\"kw-clinique\">les</span> VAS (absence de caillots obstructifs), <span class=\"kw-ttt\">décubitus latéral du côté qui saigne</span></p>","hospit":"<p><strong>Principe :</strong> <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-ttt\">milieu spécialisé</span> — toute <span class=\"kw-clinique\">hémoptysie</span> justifie une orientation hospitalière<br><strong>Sans <span class=\"kw-alerte\">signe de gravité</span> :</strong> <span class=\"kw-def\">surveillance</span> en milieu adapté + poursuite du bilan étiologique<br><strong>Grave :</strong> <span class=\"kw-alerte\">soins intensifs respiratoires</span>, surveillance continue ou <span class=\"kw-alerte\">réanimation</span> (indispensable) ; PEC multidisciplinaire (pneumologue, réanimateur, radiologue interventionnel, chirurgien thoracique)</p>","redflags":"<ul><li>Abondance importante : <span class=\"kw-chiffre\">≥ 200 mL</span> chez le sujet sain ; selon MIR <span class=\"kw-chiffre\">&gt; 100 mL</span> en 1 fois, <span class=\"kw-chiffre\">&gt; 200 mL/24h</span> (sujet sain) ou <span class=\"kw-chiffre\">&gt; 50 mL/24h</span> chez l'insuffisant respiratoire chronique</li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-clinique\">insuffisance respiratoire chronique</span> sous-jacente, <span class=\"kw-def\">comorbidités</span> respiratoires ou cardiovasculaires</li><li><span class=\"kw-alerte\">Détresse</span> respiratoire : <span class=\"kw-clinique\">FR &gt; 30/min</span>, <span class=\"kw-clinique\">SpO2 &lt; 85%</span> en <span class=\"kw-def\">air</span> ambiant, recours à l'<span class=\"kw-ttt\">O2 haut débit</span> ou à la <span class=\"kw-ttt\">ventilation mécanique</span></li><li><span class=\"kw-alerte\">Détresse</span> hémodynamique : <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">tachycardie</span> (exceptionnelle et tardive)</li><li><span class=\"kw-clinique\">Hémoptysie</span> active avec <span class=\"kw-clinique\">caillots</span></li><li>Persistance du saignement <span class=\"kw-ttt\">sous vasoconstricteurs</span></li><li>Risque de récidive : patient sous <span class=\"kw-ttt\">anticoagulant</span></li></ul>","principes":"<p>Hiérarchisation selon la gravité ; options combinables et multidisciplinaires.</p><p><strong>Traitement médical (<span class=\"kw-chiffre\">1ère ligne</span>)</strong></p><p>Le <span class=\"kw-ttt\">terlipressine</span> peut compliquer une <span class=\"kw-imagerie\">artériographie</span> ultérieure (spasme artériel)</p><ul><li>Vérifier l'absence d'obstruction des VAS (caillots pharyngolaryngés)</li><li>Arrêt systématique des <span class=\"kw-ttt\">antithrombotiques</span> (<span class=\"kw-ttt\">antiagrégant</span>, <span class=\"kw-ttt\">anticoagulant</span>) en cas d'<span class=\"kw-clinique\">hémoptysie</span> sévère</li><li><span class=\"kw-ttt\">Oxygénothérapie</span> avec interface adaptée, objectif <span class=\"kw-chiffre\">SpO2 ≥ 90-92%</span> (monitoring)</li><li><span class=\"kw-ttt\">Terlipressine</span> IV (vasoconstricteur) : <span class=\"kw-ci\">contre-indiquée si athérosclérose</span> (risque <span class=\"kw-alerte\">IDM</span>, <span class=\"kw-alerte\">AVC</span>, <span class=\"kw-alerte\">ischémie aiguë</span> de membre) ; inefficace si saignement d'origine artérielle pulmonaire</li><li>Protection des voies aériennes : <span class=\"kw-ttt\">décubitus latéral du côté qui saigne</span> ; <span class=\"kw-ttt\">intubation</span> (sonde à double lumière, ou sélective du côté sain, ou ballonnet dans la bronche souche qui saigne) ; <span class=\"kw-ci\">VNI contre-indiquée</span></li></ul><p><strong>Radiologie interventionnelle</strong></p><p>Méthode de choix pour l'<span class=\"kw-clinique\">hémoptysie</span> grave</p><ul><li><span class=\"kw-ttt\">Embolisation artérielle bronchique</span> par <span class=\"kw-imagerie\">artériographie</span> : repère l'artère en cause et l'obstrue (injection de <span class=\"kw-ttt\">particules</span> ou de <span class=\"kw-ttt\">spirales</span>)</li><li>Limite : requiert une expertise non disponible dans tous <span class=\"kw-clinique\">les</span> centres</li><li>Complications rares mais graves : <span class=\"kw-alerte\">paraplégie</span> (embolisation d'un rameau médullaire), <span class=\"kw-alerte\">nécrose œsophagienne</span> (rameau œsophagien)</li></ul><p><strong>Traitement chirurgical (radical)</strong></p><ul><li><span class=\"kw-ttt\">Lobectomie</span> (plus rarement <span class=\"kw-ttt\">pneumonectomie</span>) : arrête le saignement et prévient la récidive</li><li>Conditions : zone pathologique limitée, unilatérale ; fonction respiratoire compatible</li><li>À froid (à distance) ou à chaud en cas d'<span class=\"kw-alerte\">échec de l'embolisation</span> (<span class=\"kw-def\">mortalité</span> ≈ <span class=\"kw-chiffre\">40%</span>)</li></ul><p><strong>Traitement topique (<span class=\"kw-clinique\">hémoptysie</span> non grave)</strong></p><ul><li>Instillation locale de <span class=\"kw-ttt\">sérum physiologique à 4 °C</span> ou de <span class=\"kw-ttt\">solution adrénalinée</span> (indication anecdotique)</li><li>Toilette bronchique possible, mais <span class=\"kw-ci\">ne jamais</span> mobiliser le caillot</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Surveillance</span> :</strong> du saignement (quantification par récipients gradués), surtout s'il persiste sous vasoconstricteurs ; monitoring de la <span class=\"kw-bio\">SpO2</span><br><strong>BPCO + <span class=\"kw-clinique\">hémoptysie</span> :</strong> <span class=\"kw-ci\">ne jamais</span> attribuer à la BPCO → <span class=\"kw-imagerie\">endoscopie bronchique</span> + <span class=\"kw-imagerie\">TDM thoracique</span> systématiques + surveillance prolongée pour rechercher un <span class=\"kw-etio\">cancer bronchopulmonaire</span> sous-jacent</p>"},"liensGlobaux":[{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_205_HEMOPTYSIE-2023.pdf","label":"Collège (CEP) — Item 205 hemoptysie 2023"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/25.%20H%C3%A9moptysie.pdf","label":"CeMIR — 25. hémoptysie"},{"href":"https://radiopaedia.org/articles/haemoptysis-1","label":"Radiopaedia : Haemoptysis 1"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Hémoptysie — confirmée (vs hématémèse / épistaxis postérieure)","detail":"<h4>CAT — <span class=\"kw-clinique\">Hémoptysie</span> grave — Stratégie thérapeutique hiérarchisée selon la gravité (algorithme MIR)</h4>","branches":[{"to":"q-stable","label":"Évaluation initiale","color":"blue"}]},{"id":"q-stable","kind":"decision","label":"Angioscanner immédiatement disponible ET patient stable ? — Évaluer la disponibilité de l'angio-TDM et la stabilité du patient","branches":[{"to":"t-stabilisation","label":"Non : instable ou angioscanner indisponible","color":"amber"},{"to":"q-gravite","label":"Oui : stable + angioscanner réalisé","color":"green"}]},{"id":"t-stabilisation","kind":"terminal","label":"Mesures de stabilisation","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Terlipressine</span> IV (vasoconstricteur)</li><li><span class=\"kw-ttt\">Endoscopie bronchique d'hémostase locale</span></li></ul><h4>Objectif</h4><ul><li>Stabiliser dans l'attente de l'<span class=\"kw-imagerie\">angioscanner</span> / du plateau technique</li></ul>"},{"id":"q-gravite","kind":"decision","label":"Angioscanner : signes de gravité présents ? — IRA, hémoptysie de grande abondance, comorbidité respiratoire/CV, risque de récidive (anticoagulant)","branches":[{"to":"t-surveillance","label":"Absence de signe de gravité","color":"green"},{"to":"q-rvi","label":"Présence de signe(s) de gravité","color":"red"}]},{"id":"t-surveillance","kind":"terminal","label":"Surveillance en milieu adapté","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-def\">Surveillance</span> rapprochée en milieu adapté</li><li>Poursuite du bilan étiologique</li></ul><h4>Critère</h4><ul><li>Absence de <span class=\"kw-alerte\">signe de gravité</span> à l'<span class=\"kw-imagerie\">angioscanner</span></li></ul>"},{"id":"q-rvi","kind":"decision","label":"Embolisation artérielle bronchique : efficace ? — Radiologie vasculaire interventionnelle = traitement de 1ère intention de l'hémoptysie grave","branches":[{"to":"t-embol-ok","label":"Embolisation efficace","color":"green"},{"to":"t-chirurgie","label":"Échec / mécanisme artériel pulmonaire","color":"red"}]},{"id":"t-embol-ok","kind":"terminal","label":"Embolisation efficace → saignement contrôlé","color":"green","detail":"<h4>Conduite</h4><ul><li>Saignement contrôlé par l'<span class=\"kw-ttt\">embolisation artérielle bronchique</span></li><li><span class=\"kw-def\">Surveillance</span> + poursuite du bilan étiologique</li></ul>"},{"id":"t-chirurgie","kind":"terminal","label":"Chirurgie thoracique","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Lobectomie</span> (plus rarement <span class=\"kw-ttt\">pneumonectomie</span>)</li><li>Traitement radical : arrête le saignement et prévient la récidive</li></ul><h4>Indications</h4><ul><li>Échec de l'artério-embolisation</li><li>Mécanisme artériel pulmonaire</li><li>À chaud : <span class=\"kw-def\">mortalité</span> ≈ <span class=\"kw-chiffre\">40%</span></li></ul><h4>Conditions</h4><ul><li>Zone pathologique limitée, unilatérale</li><li>Fonction respiratoire compatible</li></ul>"}]},"cards":[{"i":"19a3df8135c6","n":205,"o":"205-1","u":"Définition","t":"Connaître la définition d’une hémoptysie","q":"Quelle est la part de la circulation pulmonaire dans les hémoptysies et quelles sont ses caractéristiques principales ?","a":"<p>La circulation pulmonaire est à l'origine de <strong>5 % des cas</strong> d'hémoptysie, mais avec une <strong>gravité accrue</strong>. C'est un régime de <strong>basse pression</strong> et de haut débit (100 % du débit cardiaque), avec les artères pulmonaires issues du ventricule droit.</p>"},{"i":"8a97624da228","n":205,"o":"205-1","u":"Définition","t":"Connaître la définition d’une hémoptysie","q":"Quelle est la définition d'une hémoptysie ?","a":"<p>L'hémoptysie est un <strong>saignement</strong> issu des <strong>voies respiratoires sous-glottiques</strong>, extériorisé ou non, traduisant une anomalie pouvant siéger à tous les étages de l'appareil respiratoire.</p>"},{"i":"a41921b7d69c","n":205,"o":"205-1","u":"Définition","t":"Connaître la définition d’une hémoptysie","q":"Quelle circulation est majoritairement à l'origine de l'hémoptysie, et quelle est sa part dans les cas d'hémoptysie ?","a":"<p>L'hémoptysie est en règle alimentée par la <strong>circulation bronchique</strong> (systémique), qui est responsable de <strong>95 % des cas</strong>.</p>"},{"i":"a6a16e7223bd","n":205,"o":"205-1","u":"Définition","t":"Connaître la définition d’une hémoptysie","q":"Quelles sont les caractéristiques principales de la circulation bronchique en termes de régime et d'origine des artères ?","a":"<p>La circulation bronchique est de <strong>haut régime et haute pression</strong> (grande circulation). Ses artères bronchiques proviennent de l'<strong>aorte thoracique descendante</strong>.</p>"},{"i":"402cbd59c7b8","n":205,"o":"205-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’hémoptysie et argumenter le diagnostic différentiel","q":"Comment doit-on définir cliniquement une hémoptysie ?","a":"<p>L'hémoptysie est caractérisée par l'<strong>expectoration par la bouche</strong> de <strong>sang rouge vif</strong>, <strong>spumeux</strong> et <strong>aéré</strong>, suite à des <strong>efforts de toux</strong>.</p>"},{"i":"45de0df74be4","n":205,"o":"205-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’hémoptysie et argumenter le diagnostic différentiel","q":"Quel est le principal piège à éviter dans le diagnostic différentiel entre hémoptysie et hématémèse ?","a":"<p>Le piège classique est que le <strong>sang retrouvé dans l'estomac peut correspondre à une hémoptysie déglutie</strong>. Il ne faut pas conclure trop vite à une hématémèse sans rechercher activement la toux et les prodromes respiratoires.</p>"},{"i":"bacc01d28c4b","n":205,"o":"205-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’hémoptysie et argumenter le diagnostic différentiel","q":"Quels sont les prodromes et signes d'accompagnement pouvant évoquer une hémoptysie ?","a":"<ul><li>Une <strong>chaleur rétrosternale</strong></li><li>Un <strong>grésillement laryngé</strong></li><li>Un <strong>goût métallique</strong> dans la bouche</li><li>Une <strong>angoisse</strong></li><li>À l'auscultation, la présence de <strong>crépitants</strong> est possible.</li></ul>"},{"i":"db0bdfa4c07d","n":205,"o":"205-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’hémoptysie et argumenter le diagnostic différentiel","q":"Quelles sont les caractéristiques permettant de distinguer une hémoptysie d'une hématémèse ?","a":"<ul><li>L'<strong>hémoptysie</strong> est d'origine <strong>sous-glottique (pulmonaire)</strong>, avec un sang <strong>rouge vif, spumeux, aéré</strong>, extériorisé par un <strong>effort de toux</strong>. Les prodromes sont une chaleur rétrosternale, un grésillement et un goût métallique.</li><li>L'<strong>hématémèse</strong> est d'origine <strong>digestive haute</strong>, avec un sang <strong>rouge foncé, non aéré</strong>, et souvent accompagné de <strong>débris alimentaires</strong>. Le sang est extériorisé par un <strong>vomissement</strong>.</li></ul>"},{"i":"f0eada196f80","n":205,"o":"205-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’hémoptysie et argumenter le diagnostic différentiel","q":"Quels sont les examens paracliniques de confirmation de l'hémoptysie et quels signes y trouver ?","a":"<ul><li>Une <strong>radiographie thoracique (RXT)</strong> peut montrer des <strong>infiltrats</strong> ou des <strong>opacités</strong> liés au comblement alvéolaire.</li><li>Une <strong>TDM thoracique</strong> peut révéler une <strong>plage en verre dépoli</strong> ou une <strong>condensation alvéolaire</strong>, et éventuellement une <strong>atélectasie</strong>.</li><li>Un <strong>lavage broncho-alvéolaire (LBA)</strong> est diagnostique d'une hémorragie intra-alvéolaire pour un <strong>score de Golde > 100</strong>.</li></ul>"},{"i":"051166daaf78","n":205,"o":"205-3","u":"Identifier une urgence","t":"Savoir rechercher des signes de gravité","q":"Quels sont les seuils de volume d'hémoptysie considérés comme graves selon les terrains ?","a":"<ul><li>Hémoptysie abondante habituelle : <strong>≥ 200 mL / 24 heures</strong> chez un sujet sain.</li><li>Hémoptysie grave d'emblée : <strong>> 100 mL en une seule fois</strong>, quel que soit le terrain.</li><li>Hémoptysie grave sur terrain fragile (ex: insuffisant respiratoire chronique) : <strong>> 50 mL / 24 heures</strong>.</li></ul>"},{"i":"7715e52f40e4","n":205,"o":"205-3","u":"Identifier une urgence","t":"Savoir rechercher des signes de gravité","q":"Quel est le risque principal associé à une hémoptysie, et pourquoi l'absence de signes de choc hémorragique est-elle trompeuse ?","a":"<p>Le risque principal associé à une hémoptysie est l'<strong>asphyxie</strong>, et non la spoliation sanguine. L'absence de choc hémorragique ou d'anémie est faussement rassurante car le volume des voies de conduction (150-200 mL) est faible et le retentissement hémodynamique est exceptionnel et tardif.</p>"},{"i":"a6c40372f349","n":205,"o":"205-3","u":"Identifier une urgence","t":"Savoir rechercher des signes de gravité","q":"Outre le volume, quels sont les critères de terrain et de retentissement clinique associés à la gravité d'une hémoptysie ?","a":"<ul><li><strong>Critères de terrain :</strong> <ul><li><strong>insuffisance respiratoire chronique</strong> sous-jacente (BPCO, fibrose, IRC), qui est un critère de gravité par lui-même.</li><li>cardiopathie ischémique (justifiant le maintien d'antithrombotiques).</li><li>persistance du saignement, particulièrement sous vasoconstricteurs.</li></ul></li><li><strong>Critères de retentissement clinique (signes de détresse respiratoire) :</strong> <ul><li>fréquence respiratoire <strong>> 30 / min</strong>.</li><li>SpO₂ <strong>< 85 %</strong> en air ambiant.</li><li>recours à l'oxygénothérapie à haut débit ou à la ventilation mécanique.</li></ul></li></ul>"},{"i":"401a5133fe28","n":205,"o":"205-4","u":"Prise en charge","t":"Connaître les modalités d’initiation du traitement symptomatique en urgence","q":"Comment doit être réalisée la protection des voies aériennes en cas d'hémoptysie sévère, et quelle technique est formellement contre-indiquée ?","a":"<p>En cas d'hémoptysie sévère nécessitant une protection des voies aériennes :<ul><li>La <strong>VNI est formellement contre-indiquée</strong>.</li><li>Recourir à l'<strong>intubation et à la ventilation mécanique invasive</strong>.</li><li>En 1<sup>re</sup> intention : utiliser une <strong>sonde d'intubation à double lumière</strong> pour protéger le poumon non saignant.</li><li>En 2<sup>nde</sup> intention (à défaut) : <ul><li>Intubation sélective du côté qui ne saigne pas.</li><li>Ou mise en place d'une sonde à ballonnet dans la bronche souche du poumon qui saigne.</li></ul></li></ul></p>"},{"i":"a4a1cba6ddcc","n":205,"o":"205-4","u":"Prise en charge","t":"Connaître les modalités d’initiation du traitement symptomatique en urgence","q":"Quelle est l'orientation immédiate d'un patient présentant une hémoptysie grave ?","a":"<p>L'orientation immédiate d'un patient avec une hémoptysie grave est une hospitalisation en <strong>milieu spécialisé</strong> : <ul><li>Soins intensifs respiratoires</li><li>Unité de surveillance continue</li><li>Réanimation</li></ul></p>"},{"i":"c002932c9ab0","n":205,"o":"205-4","u":"Prise en charge","t":"Connaître les modalités d’initiation du traitement symptomatique en urgence","q":"Quelles sont les premières mesures symptomatiques à prendre en charge en urgence face à une hémoptysie grave ?","a":"<p>Les premières mesures symptomatiques en urgence sont :<ul><li>Vérifier l'absence d'<strong>obstruction des voies aériennes supérieures</strong> (VAS) par des caillots.</li><li><strong>Arrêt systématique des antithrombotiques</strong> (antiagrégants, anticoagulants).</li><li>Administration d'<strong>oxygénothérapie</strong> pour maintenir une <strong>SpO₂ ≥ 90-92 %</strong> avec monitoring continu.</li><li>Mise en <strong>décubitus latéral du côté qui saigne</strong> (si connu) pour protéger le poumon sain.</li><li>Discuter une <strong>endoscopie d'hémostase locale</strong> si l'angioTDM n'est pas immédiatement disponible ou pour temporiser.</li><li>Administration de <strong>terlipressine IV</strong>, en l'absence de contre-indications (antécédents d'athérosclérose).</li></ul></p>"},{"i":"d8536d6370b0","n":205,"o":"205-4","u":"Prise en charge","t":"Connaître les modalités d’initiation du traitement symptomatique en urgence","q":"Quel est le rôle de la terlipressine IV dans la prise en charge d'urgence de l'hémoptysie, et quelles sont ses contre-indications et limites ?","a":"<p>La <strong>terlipressine IV</strong> est utilisée en première intention pendant la phase d'investigation en cas d'hémoptysie. Ses limites et contre-indications sont :<ul><li>Elle peut rendre l'<strong>artériographie bronchique ultérieure plus difficile</strong> (spasme artériel).</li><li>Elle est <strong>inefficace</strong> si le saignement est d'origine artérielle pulmonaire (artère pulmonaire dépourvue de cellules musculaires lisses).</li><li>Elle est <strong>formellement contre-indiquée en cas d'athérosclérose</strong> en raison du risque d'<strong>IDM</strong>, d'<strong>AVC</strong> et d'<strong>ischémie aiguë de membre inférieur</strong>. Il faut toujours rechercher des antécédents vasculaires avant la prescription.</li></ul></p>"}]};